async function enableBiometric(){if(!currentUser)return;try{const cred=await navigator.credentials.create({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),rp:{name:'Lingua'},user:{id:new TextEncoder().encode(currentUser.id),name:currentUser.email||'user',displayName:currentUser.email||'Lingua'},pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required',residentKey:'preferred'},timeout:60000}});localStorage.setItem(BIO_KEY(currentUser.id),b64u(cred.rawId));rememberBioUnlock(currentUser.id);toast('הכניסה עם טביעת אצבע / Face ID הופעלה במכשיר הזה.');renderBioButtons()}catch(e){toast('לא ניתן להפעיל כניסה ביומטרית: '+(e.message||e))}}
