function closeCover(w){w.classList.add('out');setTimeout(()=>w.remove(),450)}
async function showWelcome(){let seen=false;try{seen=sessionStorage.getItem('lingua:welcomed')==='1'}catch{}if(seen||$('#welcomeCover'))return;try{sessionStorage.setItem('lingua:welcomed','1')}catch{}const owner=isOwner();let name=learnerProfile?.display_name||'';const w=document.createElement('div');w.id='welcomeCover';w.className='welcome-cover';w.setAttribute('role','dialog');w.setAttribute('aria-modal','true');w.setAttribute('aria-labelledby','welcomeTitle');w.dir=uiLang==='he'||owner?'rtl':'ltr';w.innerHTML='<div class="welcome-inner"><img src="icon-192.png" alt="" class="welcome-logo"><h1 id="welcomeTitle">ברוכים הבאים ללימוד שפות</h1><p class="welcome-name">שלום, <b class="welcome-user"></b> 👋</p><div class="welcome-progress" id="welcomeProgress"></div><button type="button" class="primary welcome-go">'+(owner?'המשך ←':'כניסה ללמידה 🚀')+'</button></div>';document.body.appendChild(w);const go=w.querySelector('.welcome-go');go.focus();if(!name&&currentUser&&supabaseClient){try{const {data}=await supabaseClient.from('profiles').select('display_name').eq('id',currentUser.id).maybeSingle();name=data?.display_name||''}catch{}}w.querySelector('.welcome-user').textContent=name||currentUser?.email?.split('@')[0]||'';renderHomeProgress($('#welcomeProgress'));go.addEventListener('click',async()=>{if(owner){showOwnerChoice(w);return}closeCover(w);await enterWorld()})}
function showOwnerChoice(w){w.querySelector('.welcome-inner').innerHTML='<img src="icon-192.png" alt="" class="welcome-logo small"><h1 id="welcomeTitle">מה נעשה היום?</h1><div class="choice-grid"><button type="button" class="choice-big learn" data-go="learn"><span aria-hidden="true">📚</span><b>כניסה ללמידה</b><small>עולם המילים, המשפטים והמבחנים</small></button><button type="button" class="choice-big admin" data-go="admin"><span aria-hidden="true">👥</span><b>ניהול משתמשים</b><small>אישור משתמשים, סטטיסטיקה ותוכן</small></button></div>';w.querySelector('[data-go=learn]').focus();w.querySelector('[data-go=learn]').addEventListener('click',async()=>{closeCover(w);await routeLearner();await enterWorld()});w.querySelector('[data-go=admin]').addEventListener('click',async()=>{closeCover(w);setView('admin');await loadUsers();$('#usersTable')?.scrollIntoView({behavior:'smooth',block:'start'})})}
async function loadAchievements(){const root=$('#achievementsList');if(!root||!currentUser)return;try{const {data,error}=await supabaseClient.from('user_achievements').select('achievement_key,title,description,awarded_at').eq('user_id',currentUser.id).order('awarded_at',{ascending:false}).limit(100);if(error)throw error;root.innerHTML=data?.length?'<ul>'+data.map(x=>'<li><b>'+escapeHtml(x.title)+'</b> — '+escapeHtml(x.description||'')+'</li>').join('')+'</ul>':'עדיין אין הישגים. הם יתווספו ככל שתתקדם בלמידה.'}catch(e){root.textContent='לא ניתן לטעון הישגים: '+e.message}}
async function refreshLearnerStats(){
 if(!currentUser)return;
 let progressRows=[],testRows=[];
 if(navigator.onLine&&supabaseClient){
  const [progress,tests]=await Promise.all([
   supabaseClient.from('user_progress').select('content_item_id,mastery').eq('user_id',currentUser.id),
   supabaseClient.from('test_results').select('score,completed_at').eq('user_id',currentUser.id).order('completed_at',{ascending:false}).limit(100)
  ]);
  if(!progress.error)progressRows=progress.data||[];else console.warn(progress.error);
  if(!tests.error)testRows=tests.data||[];else console.warn(tests.error);
  if(!progress.error)writeLocal('progress:'+currentUser.id,Object.fromEntries(progressRows.map(x=>[x.content_item_id,x])));
  if(!tests.error)writeLocal('tests:'+currentUser.id,testRows);
 }
 const localProgress=Object.values(readLocal('progress:'+currentUser.id,{}));
 const progressById=new Map(progressRows.map(x=>[x.content_item_id,x]));
 for(const row of localProgress){const remote=progressById.get(row.content_item_id);if(!remote||new Date(row.updated_at||0)>new Date(remote.updated_at||0))progressById.set(row.content_item_id,row)}
 progressRows=[...progressById.values()];
 const localTests=readLocal('tests:'+currentUser.id,[]);
 const pendingTests=readLocal('test-queue:'+currentUser.id,[]);
 const testsById=new Map([...testRows,...localTests,...pendingTests].map(x=>[x.id||[x.completed_at,x.score,x.question_count].join(':'),x]));
 testRows=[...testsById.values()].sort((a,b)=>new Date(b.completed_at)-new Date(a.completed_at));
 const mastered=progressRows.filter(x=>x.mastery>=3).length;
 $('#learnedCount').textContent=mastered;$('#testCount').textContent=testRows.length;$('#lastScore').textContent=testRows.length?Math.round(Number(testRows[0].score))+'%':'—';
}
