async function startLevel(n){quizLevel=n;if(n===5&&learning!=='en')return;const type=n===3?'sentence':'word';if(learningType!==type||!learningItems.length)await loadLearning(type);const all=learningItems.slice(),seen=seenIds();let pool=all.filter(i=>seen.has(i.id)||learnedMap.has(i.id));if(n===1){const easy=pool.filter(i=>i.image_url&&i.source_text.length<=10);if(easy.length>=4)pool=easy}if(pool.length<4){const kind=type==='sentence'?'משפטים':'מילים';$('#quizQuestion').innerHTML='<h3 class="level-title">📚 המבחן הוא רק על מה שכבר למדת</h3><p class="quiz-ask">למדת עד עכשיו '+pool.length+' '+kind+'. צריך לפחות 4.</p><p class="quiz-ask">היכנס לתחום, הקש על כרטיסים כדי ללמוד אותם, ואז חזור למבחן.</p>';$('#quizAnswers').innerHTML='<button class="quiz-answer level-btn" type="button" id="quizBackLevels"><b>🎯 בחירת רמה אחרת</b></button>';$('#quizBackLevels').addEventListener('click',startQuiz);return}quizPool=all.length>=4?all:pool;quizItems=shuffle(pool).slice(0,Math.min(10,pool.length));quizIndex=0;quizCorrect=0;quizAnswered=false;$('#quizPanel').classList.remove('hidden');renderQuestion();$('#quizPanel').scrollIntoView({behavior:'smooth',block:'center'})}
