 m.innerHTML='<div class="item-sheet pic-game" role="dialog" aria-modal="true"><button class="item-close" type="button" aria-label="סגירה">✕</button><div class="quiz-top"><span class="quiz-level">🖼️ מה בתמונה?</span><span class="quiz-count"><b>'+(pg.i+1)+' / '+pg.items.length+'</b> · ⭐ <b>'+pg.ok+'</b></span></div><div class="quiz-progress"><i style="width:'+Math.round(pg.i/pg.items.length*100)+'%"></i></div><small class="pg-src"><span>'+(pg.mode==='exit'?'מילים עם תמונה שלמדת היום:':'מילים עם תמונה שכבר למדת:')+'</span> <b>'+pg.studied+'</b></small>'+picHtml(it)+'<p class="quiz-ask">איך אומרים ב'+(languageNames[learning]||learning)+'?</p><div class="pg-answers">'+choices.map(x=>'<button class="quiz-answer" type="button" data-pg="'+x.id+'">'+pgBtn(x)+'</button>').join('')+'</div><div id="pgFeedback" class="pg-feedback" aria-live="polite"></div><button class="primary hidden" type="button" id="pgNext">הבא ➜</button></div>';
 document.body.appendChild(m);
