function trText(s){const k=s.trim();if(!k)return s;const lead=s.slice(0,s.indexOf(k)),tail=s.slice(s.indexOf(k)+k.length);const d=T[uiLang];if(d&&d[k]!=null)return lead+d[k]+tail;for(const [re,f] of TR){const m=k.match(re);if(m&&f[uiLang])return lead+f[uiLang](...m.slice(1))+tail}return s}
