function translateTree(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=walker.nextNode())){const el=n.parentElement;if(!el||el.closest(I18N_SKIP))continue;if(n.__orig===undefined||n.nodeValue!==n.__last)n.__orig=n.nodeValue;const v=uiLang==='he'?n.__orig:trText(n.__orig);if(n.nodeValue!==v)n.nodeValue=v;n.__last=v}root.querySelectorAll('input[placeholder]').forEach(i=>{if(i.dataset.ph===undefined)i.dataset.ph=i.placeholder;const p=uiLang==='he'?i.dataset.ph:((PH[uiLang]||{})[i.dataset.ph]||i.dataset.ph);if(i.placeholder!==p)i.placeholder=p})}
