function runI18n(){i18nQueued=false;uiLang=currentUiLang();if(!$('.bio-lock'))try{localStorage.setItem('lingua:uilang',uiLang)}catch{}i18nObserver?.disconnect();const dir=uiLang==='he'?'rtl':'ltr';[$('#learnerView'),$('#itemModal .item-sheet'),$('.bio-lock-card')].forEach(e=>{if(e&&e.dir!==dir)e.dir=dir});document.querySelectorAll(I18N_SCOPE).forEach(translateTree);i18nObserver?.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['class']})}
i18nObserver=new MutationObserver(()=>{if(!i18nQueued){i18nQueued=true;setTimeout(runI18n,30)}});
